// Pick Calls — tomorrow's orders that still need a confirmation call.
const cfg = $('Config').first().json;
const out = cfg.outbound || {};
const feed = $input.first().json || {};
// ---- time helpers (business time zone, no libraries) ----
const TZ = cfg.timezone;
const MIN = 60000;
const DAY = 24 * 60 * MIN;
const pad = (n) => String(n).padStart(2, '0');
const nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());
function offsetMin(utcMs) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TZ, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
  }).formatToParts(new Date(utcMs));
  const p = {};
  for (const part of parts) p[part.type] = part.value;
  return Math.round((Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second) - utcMs) / MIN);
}
function localToUtc(y, mo, d, h, mi) {
  const guess = Date.UTC(y, mo - 1, d, h, mi);
  const first = guess - offsetMin(guess) * MIN;
  return guess - offsetMin(first) * MIN; // second pass settles days when clocks change
}
function local(ms) {
  const shifted = new Date(ms + offsetMin(ms) * MIN);
  return {
    y: shifted.getUTCFullYear(), mo: shifted.getUTCMonth() + 1, d: shifted.getUTCDate(),
    h: shifted.getUTCHours(), mi: shifted.getUTCMinutes(), dow: shifted.getUTCDay(),
  };
}
const localIso = (ms) => { const t = local(ms); return `${t.y}-${pad(t.mo)}-${pad(t.d)}T${pad(t.h)}:${pad(t.mi)}`; };
const localDate = (ms) => localIso(ms).slice(0, 10);
const dayStart = (dateText) => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(dateText); return localToUtc(+m[1], +m[2], +m[3], 0, 0); };
const at = (dateText, hhmm) => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(dateText); const [h, mi] = String(hhmm).split(':').map(Number); return localToUtc(+m[1], +m[2], +m[3], h, mi); };
const DOW = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
const spokenDay = (dateText) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', { timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long' }).format(new Date(dayStart(dateText) + 12 * 60 * MIN));
const windowOf = (id) => (cfg.windows || []).find((w) => w.id === id);
const spokenWindow = (dateText, id) => {
  const w = windowOf(id);
  return w ? `${spokenDay(dateText)}, с ${w.start} до ${w.end}` : `${spokenDay(dateText)}, интервал ${id || 'не назначен'}`;
};
const now = nowMs();
const today = localDate(now);
const nowHm = localIso(now).slice(11);
if (nowHm < (out.call_from || '10:00') || nowHm >= (out.call_until || '20:00')) return [];

const values = Array.isArray(feed.values) ? feed.values : [];
const head = (values[0] || []).map((h) => String(h).trim().toLowerCase());
const col = (row, name) => String(row[head.indexOf(name)] ?? '').trim();
const digits = (value) => String(value || '').replace(/[^\d]/g, '');
const phoneRules = cfg.phone || {};
const phone = (value) => {
  let d = digits(value);
  if (d.startsWith('00')) d = d.slice(2);
  else if (phoneRules.national_prefix && phoneRules.country_code && d.startsWith(phoneRules.national_prefix) && !d.startsWith(phoneRules.country_code)) {
    d = phoneRules.country_code + d.slice(phoneRules.national_prefix.length);
  }
  return d.length >= 9 && d.length <= 15 ? '+' + d : '';
};
const tomorrow = localDate(dayStart(today) + DAY + 12 * 60 * MIN);
const picked = [];
values.slice(1).forEach((row, i) => {
  const number = phone(col(row, 'phone'));
  const calls = Number(col(row, 'calls')) || 0;
  if (!col(row, 'order_id') || !number) return;
  if (col(row, 'delivery_date') !== tomorrow) return;
  if (!(cfg.changeable_statuses || []).includes(col(row, 'status').toLowerCase())) return;
  if (/^(да|yes|1|true)$/i.test(col(row, 'confirmed'))) return;
  if (calls >= (out.max_attempts || 2)) return;
  if (col(row, 'last_call').startsWith(today)) return; // one attempt a day; the next run tries again tomorrow
  const address = [col(row, 'city'), col(row, 'address'), col(row, 'apartment') && 'квартира ' + col(row, 'apartment')].filter(Boolean).join(', ');
  const vars = {
    order_id: col(row, 'order_id'), customer_name: col(row, 'customer_name') || 'клиент',
    delivery: spokenWindow(col(row, 'delivery_date'), col(row, 'window')), address,
  };
  const request = out.provider === 'retell'
    ? { url: `${out.retell_api_base}/v2/create-phone-call`, body: { from_number: out.retell_from_number, to_number: number, override_agent_id: out.retell_agent_id, retell_llm_dynamic_variables: vars } }
    : { url: `${out.vapi_api_base}/call`, body: { assistantId: out.vapi_assistant_id, phoneNumberId: out.vapi_phone_number_id,
        customer: { number, name: vars.customer_name }, assistantOverrides: { variableValues: vars } } };
  picked.push({ json: { row: i + 2, order_id: vars.order_id, calls, history: col(row, 'history'), request } });
});
return picked.slice(0, out.max_calls_per_run || 50);

// Mark Calls — counts the attempt on each order and builds one write for the sheet.
const cfg = $('Config').first().json;
const picked = $('Pick Calls').all();
const answers = $input.all();
// ---- time helpers (business time zone, no libraries) ----
const TZ = cfg.timezone;
const MIN = 60000;
const DAY = 24 * 60 * MIN;
const pad = (n) => String(n).padStart(2, '0');
const nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());
function offsetMin(utcMs) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TZ, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
  }).formatToParts(new Date(utcMs));
  const p = {};
  for (const part of parts) p[part.type] = part.value;
  return Math.round((Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute, +p.second) - utcMs) / MIN);
}
function localToUtc(y, mo, d, h, mi) {
  const guess = Date.UTC(y, mo - 1, d, h, mi);
  const first = guess - offsetMin(guess) * MIN;
  return guess - offsetMin(first) * MIN; // second pass settles days when clocks change
}
function local(ms) {
  const shifted = new Date(ms + offsetMin(ms) * MIN);
  return {
    y: shifted.getUTCFullYear(), mo: shifted.getUTCMonth() + 1, d: shifted.getUTCDate(),
    h: shifted.getUTCHours(), mi: shifted.getUTCMinutes(), dow: shifted.getUTCDay(),
  };
}
const localIso = (ms) => { const t = local(ms); return `${t.y}-${pad(t.mo)}-${pad(t.d)}T${pad(t.h)}:${pad(t.mi)}`; };
const localDate = (ms) => localIso(ms).slice(0, 10);
const dayStart = (dateText) => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(dateText); return localToUtc(+m[1], +m[2], +m[3], 0, 0); };
const at = (dateText, hhmm) => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(dateText); const [h, mi] = String(hhmm).split(':').map(Number); return localToUtc(+m[1], +m[2], +m[3], h, mi); };
const DOW = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
const spokenDay = (dateText) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', { timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long' }).format(new Date(dayStart(dateText) + 12 * 60 * MIN));
const windowOf = (id) => (cfg.windows || []).find((w) => w.id === id);
const spokenWindow = (dateText, id) => {
  const w = windowOf(id);
  return w ? `${spokenDay(dateText)}, с ${w.start} до ${w.end}` : `${spokenDay(dateText)}, интервал ${id || 'не назначен'}`;
};
const now = nowMs();
const head = ($('Read Orders').first().json.values || [[]])[0].map((h) => String(h).trim().toLowerCase());
const letter = (i) => (i < 26 ? String.fromCharCode(65 + i) : String.fromCharCode(64 + Math.floor(i / 26)) + String.fromCharCode(65 + (i % 26)));
const sheet = `'${String(cfg.sheet_name || 'Orders').replace(/'/g, "''")}'`;
const cell = (row, col, value) => ({ range: `${sheet}!${letter(head.indexOf(col))}${row}`, values: [[value]] });
const data = [];
const started = [];
const failed = [];
picked.forEach((item, i) => {
  const p = item.json;
  const answer = (answers[i] && answers[i].json) || {};
  const ok = !answer.error && (answer.id || answer.call_id);
  (ok ? started : failed).push(p.order_id);
  const entry = `${localIso(now)} исходящий звонок: ${ok ? 'начат, ' + (answer.id || answer.call_id) : 'не начат — ' + JSON.stringify(answer.error || answer).slice(0, 120)}`;
  // A call that never started does not use up an attempt; last_call still stops a retry the same day.
  data.push(cell(p.row, 'calls', String(ok ? p.calls + 1 : p.calls)), cell(p.row, 'last_call', localIso(now)),
    cell(p.row, 'history', ((p.history ? p.history + '\n' : '') + entry).slice(-2000)));
});
const report = ['Звонки для подтверждения доставки', `Начато: ${started.length}`, failed.length ? `Не начато: ${failed.length} (${failed.join(', ')})` : ''].filter(Boolean).join('\n');
return [{ json: { body: { valueInputOption: 'RAW', data }, report } }];
